-- Instrua domain foundation. Additive migration; existing data is preserved.
-- External providers are integration boundaries, not simulated live connections.
create table if not exists user_role_assignments (id uuid primary key, user_id uuid not null references app_users(id) on delete cascade, company_id uuid references companies(id) on delete cascade, role_code varchar(60) not null, unit_id uuid, team_id uuid, context_code varchar(80) not null default 'GENERAL', granted_by uuid references app_users(id) on delete set null, granted_at timestamptz not null default now(), revoked_at timestamptz, constraint ck_user_role_assignment_revocation check (revoked_at is null or revoked_at >= granted_at));
create index if not exists idx_role_assignment_user_company on user_role_assignments(user_id, company_id, revoked_at);
create index if not exists idx_role_assignment_company_role on user_role_assignments(company_id, role_code, revoked_at);
create table if not exists company_units (id uuid primary key, company_id uuid not null references companies(id) on delete cascade, name varchar(200) not null, code varchar(80), timezone varchar(80) not null default 'America/Sao_Paulo', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, code));
create table if not exists teams (id uuid primary key, company_id uuid not null references companies(id) on delete cascade, unit_id uuid references company_units(id) on delete set null, name varchar(200) not null, team_type varchar(80) not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists team_memberships (id uuid primary key, team_id uuid not null references teams(id) on delete cascade, user_id uuid not null references app_users(id) on delete cascade, membership_role varchar(80) not null, starts_at timestamptz not null default now(), ends_at timestamptz, created_at timestamptz not null default now(), unique(team_id, user_id, starts_at));
create index if not exists idx_team_members_user on team_memberships(user_id, ends_at);
create table if not exists cancellation_policies (id uuid primary key, company_id uuid not null references companies(id) on delete cascade, service_offering_id uuid references service_offerings(id) on delete cascade, version integer not null, title varchar(200) not null, policy_text varchar(8000) not null, deposit_amount numeric(12,2), cancellation_deadline_minutes integer, late_cancellation_fee numeric(12,2), no_show_fee numeric(12,2), currency char(3) not null default 'BRL', effective_from timestamptz not null, effective_until timestamptz, created_by uuid references app_users(id) on delete set null, created_at timestamptz not null default now(), unique(company_id, service_offering_id, version), constraint ck_policy_dates check(effective_until is null or effective_until > effective_from), constraint ck_policy_amounts check((deposit_amount is null or deposit_amount >= 0) and (late_cancellation_fee is null or late_cancellation_fee >= 0) and (no_show_fee is null or no_show_fee >= 0) and (cancellation_deadline_minutes is null or cancellation_deadline_minutes >= 0)));
create table if not exists appointment_policy_acceptances (id uuid primary key, appointment_id uuid not null references appointments(id) on delete cascade, policy_id uuid not null references cancellation_policies(id), accepted_by_user_id uuid references app_users(id) on delete set null, accepted_at timestamptz not null default now(), policy_snapshot jsonb not null, acceptance_channel varchar(40) not null default 'WEB', ip_hash varchar(128), unique(appointment_id));
alter table appointments add column if not exists patient_user_id uuid references app_users(id) on delete set null;
alter table appointments add column if not exists unit_id uuid references company_units(id) on delete set null;
alter table appointments add column if not exists cancellation_initiator varchar(30);
alter table appointments add column if not exists cancellation_policy_id uuid references cancellation_policies(id) on delete set null;
create index if not exists idx_appointments_patient_start on appointments(patient_user_id, starts_at);
create index if not exists idx_appointments_company_unit_start on appointments(company_id, unit_id, starts_at);
create table if not exists contact_preferences (id uuid primary key, user_id uuid not null references app_users(id) on delete cascade, channel varchar(30) not null, purpose varchar(80) not null, permitted boolean not null default false, consent_version varchar(40), changed_at timestamptz not null default now(), source varchar(40) not null default 'SETTINGS', unique(user_id, channel, purpose));
create table if not exists notification_outbox (id uuid primary key, company_id uuid references companies(id) on delete set null, recipient_user_id uuid references app_users(id) on delete set null, appointment_id uuid references appointments(id) on delete set null, channel varchar(30) not null, purpose varchar(80) not null, template_key varchar(120) not null, payload jsonb not null default '{}'::jsonb, status varchar(30) not null default 'PENDING', not_before timestamptz not null default now(), attempts integer not null default 0, provider_message_id varchar(500), last_error_code varchar(100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_notification_outbox_ready on notification_outbox(status, not_before);
create table if not exists care_encounters (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, patient_id uuid not null references patients(id) on delete restrict, unit_id uuid references company_units(id) on delete set null, appointment_id uuid references appointments(id) on delete set null, lead_professional_user_id uuid references app_users(id) on delete set null, status varchar(30) not null default 'OPEN', started_at timestamptz not null default now(), ended_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint ck_encounter_dates check(ended_at is null or ended_at >= started_at));
create index if not exists idx_encounters_patient_date on care_encounters(patient_id, started_at desc);
create index if not exists idx_encounters_company_date on care_encounters(company_id, started_at desc);
create table if not exists clinical_records (id uuid primary key, encounter_id uuid not null references care_encounters(id) on delete restrict, record_type varchar(60) not null, content jsonb not null, author_user_id uuid not null references app_users(id) on delete restrict, authored_at timestamptz not null default now(), amended_record_id uuid references clinical_records(id) on delete restrict, status varchar(30) not null default 'SIGNED', source_system varchar(100) not null default 'INSTRUA', created_at timestamptz not null default now());
create index if not exists idx_clinical_records_encounter_date on clinical_records(encounter_id, authored_at);
create table if not exists clinical_access_grants (id uuid primary key, company_id uuid not null references companies(id) on delete cascade, patient_id uuid not null references patients(id) on delete cascade, user_id uuid not null references app_users(id) on delete cascade, encounter_id uuid references care_encounters(id) on delete cascade, access_scope varchar(40) not null, reason varchar(500) not null, granted_by uuid references app_users(id) on delete set null, granted_at timestamptz not null default now(), expires_at timestamptz, revoked_at timestamptz, constraint ck_access_grant_expiry check(expires_at is null or expires_at > granted_at));
create index if not exists idx_clinical_grant_lookup on clinical_access_grants(user_id, patient_id, company_id, revoked_at);
create table if not exists clinical_document_requests (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, patient_id uuid not null references patients(id) on delete restrict, encounter_id uuid references care_encounters(id) on delete restrict, requested_by uuid not null references app_users(id) on delete restrict, document_type varchar(60) not null, purpose varchar(1000), status varchar(40) not null default 'REQUESTED', assigned_clinician_id uuid references app_users(id) on delete set null, decision_note varchar(2000), requested_at timestamptz not null default now(), decided_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists clinical_documents (id uuid primary key, request_id uuid references clinical_document_requests(id) on delete restrict, company_id uuid not null references companies(id) on delete restrict, patient_id uuid not null references patients(id) on delete restrict, encounter_id uuid references care_encounters(id) on delete restrict, document_type varchar(60) not null, storage_key varchar(1000) not null, document_status varchar(40) not null, signature_method varchar(40), issued_by uuid references app_users(id) on delete restrict, issued_at timestamptz, provenance jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists business_orders (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, customer_user_id uuid references app_users(id) on delete set null, order_type varchar(50) not null, status varchar(40) not null default 'PENDING', currency char(3) not null default 'BRL', subtotal numeric(12,2) not null default 0, fees numeric(12,2) not null default 0, total numeric(12,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint ck_order_amounts check(subtotal >= 0 and fees >= 0 and total >= 0));
create table if not exists payment_transactions (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, order_id uuid references business_orders(id) on delete restrict, appointment_id uuid references appointments(id) on delete restrict, provider varchar(60) not null, provider_transaction_id varchar(500), status varchar(40) not null default 'CREATED', amount numeric(12,2) not null check(amount >= 0), currency char(3) not null default 'BRL', idempotency_key varchar(120) not null, provider_payload_redacted jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(provider, idempotency_key));
create table if not exists finance_entries (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, entry_type varchar(30) not null, category varchar(100) not null, description varchar(1000) not null, amount numeric(12,2) not null check(amount >= 0), currency char(3) not null default 'BRL', due_at date, settled_at timestamptz, status varchar(30) not null default 'PENDING', source_type varchar(60), source_id uuid, created_by uuid references app_users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_finance_entries_company_due on finance_entries(company_id, due_at, status);
create table if not exists fiscal_documents (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, provider varchar(80) not null, document_type varchar(40) not null, status varchar(40) not null default 'DRAFT', external_document_id varchar(500), idempotency_key varchar(120) not null, payload_redacted jsonb not null default '{}'::jsonb, last_error_code varchar(100), issued_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, provider, idempotency_key));
create table if not exists journey_events (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, user_id uuid not null references app_users(id) on delete restrict, employee_id uuid references employees(id) on delete set null, event_type varchar(40) not null, occurred_at timestamptz not null, source varchar(40) not null, location_reference varchar(500), evidence_reference varchar(1000), correction_request_id uuid, created_at timestamptz not null default now());
create index if not exists idx_journey_events_user_time on journey_events(company_id, user_id, occurred_at desc);
create table if not exists journey_correction_requests (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, requested_by uuid not null references app_users(id) on delete restrict, journey_event_id uuid references journey_events(id) on delete restrict, requested_change jsonb not null, justification varchar(2000) not null, status varchar(30) not null default 'PENDING', decided_by uuid references app_users(id) on delete set null, decided_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists social_posts (id uuid primary key, author_user_id uuid not null references app_users(id) on delete restrict, company_id uuid references companies(id) on delete set null, audience varchar(30) not null default 'PUBLIC', body varchar(10000) not null, status varchar(30) not null default 'PENDING', moderated_by uuid references app_users(id) on delete set null, moderated_at timestamptz, moderation_reason varchar(1000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists social_reports (id uuid primary key, post_id uuid not null references social_posts(id) on delete cascade, reporter_user_id uuid references app_users(id) on delete set null, reason_code varchar(80) not null, details varchar(2000), status varchar(30) not null default 'OPEN', assigned_to uuid references app_users(id) on delete set null, resolved_at timestamptz, created_at timestamptz not null default now());
create table if not exists social_comments (id uuid primary key, post_id uuid not null references social_posts(id) on delete cascade, author_user_id uuid not null references app_users(id) on delete restrict, body varchar(5000) not null, status varchar(30) not null default 'PENDING', moderated_by uuid references app_users(id) on delete set null, moderated_at timestamptz, created_at timestamptz not null default now());
create table if not exists product_opportunities (id uuid primary key, company_id uuid not null references companies(id) on delete cascade, title varchar(255) not null, description varchar(4000), opportunity_type varchar(40) not null, status varchar(30) not null default 'OPEN', price numeric(12,2), currency char(3) not null default 'BRL', starts_at timestamptz, ends_at timestamptz, published_by uuid references app_users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists opportunity_applications (id uuid primary key, opportunity_id uuid not null references product_opportunities(id) on delete cascade, applicant_user_id uuid not null references app_users(id) on delete cascade, message varchar(2000), status varchar(30) not null default 'SUBMITTED', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(opportunity_id, applicant_user_id));
create table if not exists organization_subscriptions (id uuid primary key, company_id uuid not null references companies(id) on delete restrict, plan_code varchar(60) not null, status varchar(30) not null default 'TRIAL', billing_interval varchar(20) not null default 'MONTHLY', starts_at timestamptz not null default now(), ends_at timestamptz, external_customer_id varchar(500), external_subscription_id varchar(500), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists integration_jobs (id uuid primary key, company_id uuid references companies(id) on delete set null, domain varchar(60) not null, provider varchar(80) not null, operation varchar(100) not null, status varchar(30) not null default 'PENDING', idempotency_key varchar(120) not null, request_metadata jsonb not null default '{}'::jsonb, result_metadata jsonb not null default '{}'::jsonb, retry_count integer not null default 0, next_attempt_at timestamptz not null default now(), last_error_code varchar(100), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(provider, idempotency_key));
create table if not exists security_events (id uuid primary key, actor_user_id uuid references app_users(id) on delete set null, company_id uuid references companies(id) on delete set null, event_code varchar(100) not null, outcome varchar(30) not null, request_id varchar(120), ip_hash varchar(128), user_agent_hash varchar(128), metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now());
create index if not exists idx_security_events_company_time on security_events(company_id, occurred_at desc);
-- Shared personal profile: non-clinical account data is reusable across organizations.
create table if not exists user_profiles (user_id uuid primary key references app_users(id) on delete cascade, phone varchar(60), document_number varchar(100), birth_date date, preferred_contact_channel varchar(30), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
-- Payment provider token references only; never store PAN, CVV, or raw payment credentials.
create table if not exists user_payment_methods (id uuid primary key, user_id uuid not null references app_users(id) on delete cascade, provider varchar(80) not null, provider_method_token varchar(1000) not null, card_brand varchar(40), last_four char(4), status varchar(30) not null default 'PENDING_VERIFICATION', is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(provider, provider_method_token));
-- Health coverage registration is not proof of eligibility or authorization for a procedure.
create table if not exists patient_coverages (id uuid primary key, user_id uuid not null references app_users(id) on delete cascade, payer_name varchar(200) not null, plan_name varchar(200), member_number varchar(200) not null, card_holder_name varchar(200), valid_until date, status varchar(30) not null default 'SELF_REPORTED', verification_provider varchar(100), verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_patient_coverages_user on patient_coverages(user_id, status);
